/**
 * Fork test accounts, generated by anvil itself (`--mnemonic-random --config-out <file>`).
 * Keys stay in that 0600 file outside the repo and in memory only; this module never
 * returns them to callers except to the local signer, and never logs them.
 */
import { readFileSync, statSync } from "node:fs";
import { getAddress, type Address, type Hex } from "viem";
import { FORK_CHAIN_ID } from "./fork";

export interface ForkAccounts {
  file: string;
  addresses: Address[];
  keyFor(address: string): Hex | null;
}

export function loadForkAccounts(file: string): ForkAccounts {
  const st = statSync(file);
  if ((st.mode & 0o077) !== 0) throw new Error(`fork accounts file must not be group/world readable (mode ${(st.mode & 0o777).toString(8)})`);
  const j = JSON.parse(readFileSync(file, "utf8")) as { available_accounts?: string[]; private_keys?: string[]; chain_id?: number };
  if (j.chain_id !== undefined && Number(j.chain_id) !== FORK_CHAIN_ID) throw new Error(`fork accounts file is for chain ${j.chain_id}, expected ${FORK_CHAIN_ID}`);
  const addresses = (j.available_accounts ?? []).map((a) => getAddress(a));
  const keys = new Map(addresses.map((a, i) => [a, (j.private_keys ?? [])[i] as Hex | undefined]));
  return { file, addresses, keyFor: (a) => keys.get(getAddress(a)) ?? null };
}
